create table public.purchase_details (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_id bigint not null references public.purchases(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,purchase_without_tax numeric(14,4) not null default 0,purchase_with_tax numeric(14,4) not null default 0,profit_percent numeric(14,4) not null default 0,sales_price numeric(14,4) not null default 0,wholesale_price numeric(14,4) not null default 0,quantities integer not null default 0,batch_no text,expire_date date);
create index purchase_details_business_idx on public.purchase_details(business_id);
create table public.sale_details (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,sale_id bigint not null references public.sales(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,price numeric(14,2) not null default 0,purchase_price numeric(14,2) not null default 0,loss_profit numeric(14,2) not null default 0,batch_no text,expire_date date,quantities integer not null default 0);
create index sale_details_business_idx on public.sale_details(business_id);
create table public.purchase_returns (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_id bigint not null references public.purchases(id) on delete cascade,invoice_no text,return_date timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.purchase_return_details (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_return_id bigint not null references public.purchase_returns(id) on delete cascade,purchase_detail_id bigint not null references public.purchase_details(id) on delete cascade,return_amount numeric(14,2) not null default 0,return_qty integer not null default 0);
create table public.sale_returns (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,sale_id bigint not null references public.sales(id) on delete cascade,invoice_no text,return_date timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sale_return_details (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,sale_return_id bigint not null references public.sale_returns(id) on delete cascade,sale_detail_id bigint not null references public.sale_details(id) on delete cascade,return_amount numeric(14,2) not null default 0,return_qty integer not null default 0);
do $$ declare t text; begin for t in select unnest(array['purchase_details','sale_details','purchase_returns','purchase_return_details','sale_returns','sale_return_details']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on table public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select public.current_business_id())) with check (business_id=(select public.current_business_id()))',t||'_tenant_policy',t); end loop; end $$;